import{_ as a,o as d,c as e,a2 as o}from"./chunks/framework.DGvnA5EY.js";const s="/workbuddy-guide/assets/01-news-digest.DRgV_uPN.png",q=JSON.parse('{"title":"第 15 章 资讯整合：把信息流变成每日通知","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 你每天被热搜、公众号、群消息淹没，却总觉得\\"没记住什么\\"。这一章教你用 WorkBuddy 把信息反向推给你：设定好关注点，让它定时去搜集、汇总、精简…","frontmatter":{"title":"第 15 章 资讯整合：把信息流变成每日通知"},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 15 章 资讯整合：把信息流变成每日通知/index.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 15 章 资讯整合：把信息流变成每日通知/index.md","lastUpdated":1791615980000}'),r={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 15 章 资讯整合：把信息流变成每日通知/index.md"};function l(n,t,i,h,u,p){return d(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="第-15-章-资讯整合-把信息流变成每日通知" tabindex="-1">第 15 章 资讯整合：把信息流变成每日通知 <a class="header-anchor" href="#第-15-章-资讯整合-把信息流变成每日通知" aria-label="Permalink to &quot;第 15 章 资讯整合：把信息流变成每日通知&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）</p></blockquote><p>你每天被热搜、公众号、群消息淹没，却总觉得&quot;没记住什么&quot;。这一章教你用 WorkBuddy 把信息<strong>反向推给你</strong>：设定好关注点，让它定时去搜集、汇总、精简，每天早上把一条 干净的简报送到你手机（用到第一篇第 7 章连接器、第 8 章小程序/IM 推送、第 10 章 自动化）。</p><p><img src="'+s+`" alt="一只小黑把四面八方飞来的新闻纸片收进一个漏斗，另一头吐出一张整齐的简报" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解&quot;资讯整合&quot;，与实际软件界面无关。</em></p><h2 id="一、先想清楚-这份简报要交付什么" tabindex="-1">一、先想清楚：这份简报要交付什么 <a class="header-anchor" href="#一、先想清楚-这份简报要交付什么" aria-label="Permalink to &quot;一、先想清楚：这份简报要交付什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>要说清什么</th><th>示例</th></tr></thead><tbody><tr><td>目标</td><td>简报帮你做什么决定</td><td>每天 3 分钟知道 AI/新能源有没有大事</td></tr><tr><td>受众</td><td>谁看</td><td>只有我自己</td></tr><tr><td>材料</td><td>信息从哪来</td><td>指定几个网站/RSS/我关注的账号</td></tr><tr><td>格式</td><td>要什么形态</td><td>每条&quot;一句话+来源链接&quot;，总数不超 12 条</td></tr><tr><td>验收</td><td>怎么判断可用</td><td>只讲我关心的、来源可追溯、没编</td></tr></tbody></table><h2 id="二、先选对-skill-资讯整合的组合" tabindex="-1">二、先选对 Skill：资讯整合的组合 <a class="header-anchor" href="#二、先选对-skill-资讯整合的组合" aria-label="Permalink to &quot;二、先选对 Skill：资讯整合的组合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式 / Skill</th><th>适合处理</th><th>本章怎么用</th><th>注意点</th></tr></thead><tbody><tr><td><strong>连接器（新闻/RSS/社交源）</strong></td><td>接入信息源</td><td>接上才够得着内容</td><td>接法见第一篇第 7 章</td></tr><tr><td><strong>Browser Automation</strong></td><td>抓动态网页/没 RSS 的站</td><td>定时取页面内容</td><td>注意站点版权与频率</td></tr><tr><td><strong>自动化（第一篇第 10 章）</strong></td><td>每天定时跑</td><td>&quot;每天 8 点生成简报&quot;</td><td>无人值守要抽查</td></tr><tr><td><strong>微信小程序 / IM 推送</strong></td><td>结果送到手机</td><td>简报推到微信/小程序</td><td>见第一篇第 8、10 章</td></tr><tr><td><strong>腾讯文档</strong></td><td>存简报存档可回看</td><td>每日一份沉淀</td><td>需授权</td></tr><tr><td><strong>find-skills</strong></td><td>找更专业的资讯技能</td><td>如&quot;行业研报摘要&quot;类</td><td>零成本入口</td></tr></tbody></table><h2 id="三、真实可复制提示词" tabindex="-1">三、真实可复制提示词 <a class="header-anchor" href="#三、真实可复制提示词" aria-label="Permalink to &quot;三、真实可复制提示词&quot;">​</a></h2><h3 id="提示词-1-每日简报-手动先跑一次看效果" tabindex="-1">提示词 1｜每日简报（手动先跑一次看效果） <a class="header-anchor" href="#提示词-1-每日简报-手动先跑一次看效果" aria-label="Permalink to &quot;提示词 1｜每日简报（手动先跑一次看效果）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我做一份今日简报，只关注两条线：【AI 大模型】和【新能源汽车】。</span></span>
<span class="line"><span>从【指定网站/RSS 列表】搜集，各取 3 条最重要的，每条格式为：一句话结论 + 来源链接。</span></span>
<span class="line"><span>不要写&quot;小编点评&quot;，只要事实；总长度不超过 600 字；末尾列出来源清单。</span></span></code></pre></div><h3 id="提示词-2-把它变成自动化-配合第一篇第-10-章" tabindex="-1">提示词 2｜把它变成自动化（配合第一篇第 10 章） <a class="header-anchor" href="#提示词-2-把它变成自动化-配合第一篇第-10-章" aria-label="Permalink to &quot;提示词 2｜把它变成自动化（配合第一篇第 10 章）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>创建一个自动化任务：每天上午 8:00 运行上面的简报提示词，</span></span>
<span class="line"><span>结果推送到我的微信，并在腾讯文档新建&quot;每日简报/日期&quot;存档。</span></span>
<span class="line"><span>如果某天没有相关新闻，就发一句&quot;今日无重大更新&quot;。</span></span></code></pre></div><h3 id="提示词-3-每周复盘-升级版" tabindex="-1">提示词 3｜每周复盘（升级版） <a class="header-anchor" href="#提示词-3-每周复盘-升级版" aria-label="Permalink to &quot;提示词 3｜每周复盘（升级版）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每周日 21:00，把本周简报里出现 2 次以上的主题做成&quot;本周值得跟进&quot;清单，</span></span>
<span class="line"><span>每条写：主题、为什么重要、一个可执行的动作。推送到微信。</span></span></code></pre></div><h2 id="四、执行步骤表-搭一条流水线" tabindex="-1">四、执行步骤表（搭一条流水线） <a class="header-anchor" href="#四、执行步骤表-搭一条流水线" aria-label="Permalink to &quot;四、执行步骤表（搭一条流水线）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>WorkBuddy 做什么</th><th>你要确认什么</th></tr></thead><tbody><tr><td>1</td><td>接好信息源连接器</td><td>源是你真关心的，不是全量</td></tr><tr><td>2</td><td>先手动跑一次提示词 1</td><td>内容质量、长度、来源对不对</td></tr><tr><td>3</td><td>满意后设成自动化（提示词 2）</td><td>推送渠道、时间对不对</td></tr><tr><td>4</td><td>偶尔抽查简报</td><td>有没有编内容、链接失效</td></tr></tbody></table><h2 id="五、让简报真的-为你定制" tabindex="-1">五、让简报真的&quot;为你定制&quot; <a class="header-anchor" href="#五、让简报真的-为你定制" aria-label="Permalink to &quot;五、让简报真的&quot;为你定制&quot;&quot;">​</a></h2><p>别只说&quot;搜新闻&quot;，要说清<strong>你关心什么、不关心什么</strong>：行业只盯你所在领域；语气要 &quot;发生了什么&quot;不要&quot;点评&quot;；长度强制上限，防止它越写越嗨。</p><h2 id="六、零成本-skill-把-我的简报-固化" tabindex="-1">六、零成本 Skill：把&quot;我的简报&quot;固化 <a class="header-anchor" href="#六、零成本-skill-把-我的简报-固化" aria-label="Permalink to &quot;六、零成本 Skill：把&quot;我的简报&quot;固化&quot;">​</a></h2><p>跑顺提示词 1 后，用 <code>skill-creator</code> 固化成&quot;我的每日简报&quot;技能，以后自动化直接调用， 不用每次重写长提示词。</p><h2 id="七、实际效果与验收标准" tabindex="-1">七、实际效果与验收标准 <a class="header-anchor" href="#七、实际效果与验收标准" aria-label="Permalink to &quot;七、实际效果与验收标准&quot;">​</a></h2><p><strong>实际效果</strong>：每天早上一睁眼，手机一条干净简报，三分钟看完。</p><p><strong>验收标准</strong>：</p><ul><li>[ ] 只讲你指定的主题，没有凑数</li><li>[ ] 每条有来源链接，可追溯</li><li>[ ] 长度符合上限，没编内容（抽查确认）</li><li>[ ] 推送真的到了手机（小程序/微信）</li></ul><h2 id="八、一个必须记住的坑" tabindex="-1">八、一个必须记住的坑 <a class="header-anchor" href="#八、一个必须记住的坑" aria-label="Permalink to &quot;八、一个必须记住的坑&quot;">​</a></h2><p>自动化是&quot;无人值守&quot;跑的（第一篇第 10 章讲过）。<strong>定期回看一眼简报质量</strong>：信息源 变了、链接失效了、它开始编内容了——这些要靠你偶尔抽查发现。别设完就彻底撒手。</p><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p><strong>信息源</strong>：你让 AI 去取信息的出处，如网站、RSS、账号。接上才够得着。</p><p><strong>简报（Digest）</strong>：把多篇信息压缩成一份简短汇总，省你去逐条看。</p><p><strong>RSS</strong>：一种订阅网站更新的标准格式，很多博客/媒体提供，适合做信息源。</p><p><strong>零成本 Skill</strong>：用 skill-creator 把周常简报固化成专属技能。</p></blockquote><h2 id="本章任务清单" tabindex="-1">本章任务清单 <a class="header-anchor" href="#本章任务清单" aria-label="Permalink to &quot;本章任务清单&quot;">​</a></h2><ul><li>[ ] 用提示词 1 手动跑一次&quot;每日简报&quot;看效果</li><li>[ ] 满意后设成自动化，每天早上推送到手机</li><li>[ ] 设个每周抽查：确认简报没跑偏、没编内容</li></ul><hr><p><em>下一篇：第 16 章——收藏不是知识管理，能再次用起来才是。</em></p><hr><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>`,36)])])}const b=a(r,[["render",l]]);export{q as __pageData,b as default};
